/**
 * Checks the committed boundary asset still covers every live parking.
 *
 * The asset is generated by `yarn geo:build` and committed; it is deliberately
 * not rebuilt in CI, because that would make every build depend on Overpass.
 * The consequence is that it goes stale silently: a parking appearing somewhere
 * new — a German city the prune never reached, say — simply renders with no
 * municipality and vanishes from the filter, and nobody finds out.
 *
 * This turns that into a signal. One API call, no Overpass, a second or two.
 *
 *   yarn geo:check
 *
 * Exits non-zero when parkings cannot be placed, so it can gate a scheduled
 * run. The fix is always the same: `yarn geo:build` and commit the result.
 */

import {
  fetchParkingCoordinates,
  loadCommittedDataset,
} from './lib/parking-coordinates.mjs'

const log = (...m) => console.log('[geo:check]', ...m)

const [points, geo] = await Promise.all([
  fetchParkingCoordinates({ log: (m) => log(m) }),
  loadCommittedDataset(),
])

log(`${points.length} live parking coordinates against ${geo.index.length} bundled municipalities`)

const unresolved = []
const approximate = []
const countries = new Map()

for (const point of points) {
  const hit = geo.resolve(point.lon, point.lat)
  if (!hit) {
    unresolved.push(point)
    continue
  }
  if (hit.approx) approximate.push({ ...point, hit })
  countries.set(hit.country, (countries.get(hit.country) ?? 0) + 1)
}

const exact = points.length - unresolved.length - approximate.length
log(`exact ${exact} · approximate ${approximate.length} · unresolved ${unresolved.length}`)
log(
  'by country: ' +
    [...countries.entries()].sort((a, b) => b[1] - a[1]).map(([c, n]) => `${c}=${n}`).join(' ')
)

for (const point of approximate.slice(0, 10)) {
  log(`  ~ ${point.label} (${point.lon},${point.lat}) -> ${point.hit.name} (nearest centroid)`)
}
for (const point of unresolved.slice(0, 10)) {
  log(`  ! ${point.label} (${point.lon},${point.lat}) -> no municipality`)
}

// A GitHub step summary, when running in Actions.
if (process.env.GITHUB_STEP_SUMMARY) {
  const { appendFileSync } = await import('node:fs')
  const rows = [
    '### Municipality boundary coverage',
    '',
    `| exact | approximate | unresolved |`,
    `|---|---|---|`,
    `| ${exact} | ${approximate.length} | ${unresolved.length} |`,
  ]
  if (unresolved.length) {
    rows.push(
      '',
      `**${unresolved.length} parking(s) cannot be placed.** Run \`yarn geo:build\` and commit \`src/assets/data/\`.`,
      '',
      ...unresolved.slice(0, 20).map((p) => `- ${p.label} (${p.lon}, ${p.lat})`)
    )
  }
  appendFileSync(process.env.GITHUB_STEP_SUMMARY, rows.join('\n') + '\n')
}

if (unresolved.length) {
  console.error(
    `\n[geo:check] FAIL: ${unresolved.length} parking(s) have no municipality. ` +
      `The bundled boundaries no longer cover where the data is. ` +
      `Run 'yarn geo:build' and commit src/assets/data/.`
  )
  process.exit(1)
}

log('boundaries still cover every live parking')
